package policy

import "errors"

var ErrForbidden = errors.New("forbidden")
type Actor struct { UserID, TenantID, Role, Status string }
type Order struct { UserID, TenantID string }

func CanReadOrder(actor Actor, order Order) error {
    if actor.Status != "active" { return ErrForbidden }
    if actor.Role == "admin" { return nil }
    if actor.TenantID != order.TenantID { return ErrForbidden }
    if actor.UserID != order.UserID { return ErrForbidden }
    return nil
}
